console.log("CONSISTENT HASH RING: What");
function h(s){ var x=0; for(var i=0;i<s.length;i++){ x=((x*31)+s.charCodeAt(i))|0; } return (x>>>0)%360; }
var nodes=["n1","n2","n3"], keys=["user:1","user:2","user:3","user:4","user:5","user:6"];
keys.forEach(function(k){ var kh=h(k), best=nodes[0], bd=360; nodes.forEach(function(n){ var nh=h(n), d=(kh-nh+360)%360; if(d<bd){bd=d;best=n;} }); console.log(k+" -> "+best); });
console.log("Adding a node moves only neighboring keys: minimal remapping.");

